using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Windows.Forms;
namespace RcsMap {
 public static class CorrectionTests {
  static int count;
  static void Check(bool ok,string name){if(!ok)throw new Exception("correction model: "+name);count++;}
  static void Throws(Action action,string name){bool caught=false;try{action();}catch{caught=true;}Check(caught,name);}
  public static HardwareSource Source(){return new HardwareSource{Id="11111111111111111111111111111111",Name="测试独立定位适配器",Axes=7,Independent=true,MapAligned=true,BindingReady=true,ReadFunction="test_observer_read",Reference="relative"};}
  static string Profile(HardwareSource s){var p=new HardwareProfile{Version=1,Sources=new List<HardwareSource>{s}};using(var m=new MemoryStream()){new System.Runtime.Serialization.Json.DataContractJsonSerializer(typeof(HardwareProfile)).WriteObject(m,p);return Encoding.UTF8.GetString(m.ToArray());}}
  public static MapDocument Fixture(){var d=MapDocument.Demo();d.Obstacles.Clear();CorrectionRules.Import(d,Profile(Source()));d.Points[0].Corrections=new List<CorrectionTemplate>{new CorrectionTemplate{Id="22222222222222222222222222222222",SourceId=Source().Id,Axes=3,Kind=0,Name="只刷新XY",Enabled=true}};return d;}
  public static void WriteFixture(string folder){Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"correction-fixture.json"),Fixture().Json(),new UTF8Encoding(false));}
  public static void Run(string folder){Directory.CreateDirectory(folder);var d=MapDocument.Demo();Check(d.Points.All(p=>p.CorrectionMode==0&&!CorrectionRules.Items(p).Any()),"new defaults empty and legacy off");string initial=d.Json();Check(!initial.Contains("Corrections")&&!initial.Contains("HardwareSources"),"no phantom hardware fields");d.Points[0].CorrectionMode=2;string old=d.Json();var legacy=MapDocument.Parse(old);Check(legacy.Json()==old,"old map retains original mode as record");Check(!CorrectionRules.Items(legacy.Points[0]).Any(),"old mode never becomes template");var oldFiles=Exporter.Generate(legacy).ToDictionary(x=>x.Key,x=>x.Value.Replace("\r\n","\n"));Check(!oldFiles["rcs_route.c"].Contains(" 2u, 2u, "),"legacy mode not emitted");Check(oldFiles["rcs_route.c"].Contains("rcs_nav_bind_corrections"),"empty groups bound explicitly");Check(oldFiles["rcs_actions.c"].Contains("default:\n        return 0;"),"unavailable observation cannot fake completion");
   var source=Source();CorrectionRules.Import(d,Profile(source));Check(d.Version==5&&d.HardwareSources.Count==1,"import upgrades to v5");Check(d.Points.All(p=>!CorrectionRules.Items(p).Any()),"hardware import adds no corrections");string before=d.Json();Throws(()=>CorrectionRules.Import(d,Profile(source)),"duplicate source import rejected");Check(d.Json()==before,"failed import atomic");Check(MapDocument.Parse(before).Json()==before,"hardware roundtrip");
   d=Fixture();Check(d.Validate().Count==0,"valid independent refresh fixture");DraftRules.Check(d);Check(true,"hardware map can save as draft");Check(d.Clone().Points[0].Corrections[0].Id==d.Points[0].Corrections[0].Id,"stable correction IDs");var files=Exporter.Generate(d).ToDictionary(x=>x.Key,x=>x.Value.Replace("\r\n","\n"));Check(files.Count==19,"fifteen-file export contract");Check(files["rcs_actions.c"].Contains("return test_observer_read(sample);"),"real adapter call generated");Check(files["rcs_route.c"].Contains("point_correction_0")&&files["rcs_route.c"].Contains("route_corrections"),"per-point correction table generated");Check(files["rcs_actions.c"].Contains("OBS_"+source.Id.ToUpperInvariant()),"observer user region keyed by source identity");
   var bad=Source();bad.Kind="motor_encoder";Throws(()=>CorrectionRules.ParseProfile(Profile(bad)),"drive encoder cannot be imported as independent source");bad=Source();bad.Kind="imu";bad.Axes=3;Throws(()=>CorrectionRules.ParseProfile(Profile(bad)),"IMU cannot declare XY capability");
   var c=d.Clone();c.HardwareSources[0].Axes=4;Check(CorrectionRules.Validate(c).Any(),"yaw-only cannot correct XY");c=d.Clone();c.HardwareSources[0].BindingReady=false;Check(CorrectionRules.Validate(c).Any(),"unbound source cannot enable");c.Points[0].Corrections[0].Enabled=false;Check(CorrectionRules.Validate(c).Count==0,"pending disabled template can be saved");Check(!Exporter.Generate(c)["rcs_route.c"].Contains("static const rcs_correction point_correction"),"disabled templates omitted");
   c=d.Clone();c.HardwareSources[0].Independent=false;Throws(()=>c.StructuralCheck(),"bound drive-source declaration rejected");c=d.Clone();c.HardwareSources[0].MapAligned=false;Throws(()=>c.StructuralCheck(),"unaligned binding rejected");c=d.Clone();c.HardwareSources[0].DriverHeader="../bad.h";Throws(()=>c.StructuralCheck(),"header traversal rejected");c=d.Clone();c.HardwareSources[0].ReadFunction="a(); bad";Throws(()=>c.StructuralCheck(),"function injection rejected");c=d.Clone();c.HardwareSources[0].DriverHeader="a.h\n#include x";Throws(()=>c.StructuralCheck(),"header newline rejected");c=d.Clone();c.Version=3;Throws(()=>c.StructuralCheck(),"old schema cannot ignore hardware");c=d.Clone();c.Points[0].Corrections[0].Kind=2;Check(CorrectionRules.Validate(c).Any(),"kind and axes must agree");c=d.Clone();c.Points[0].Corrections[0].MaxAgeMs=Double.NaN;Check(CorrectionRules.Validate(c).Any(),"nonfinite limits rejected");
   string output=Path.Combine(folder,"export");Exporter.Export(d,output);string actionFile=Path.Combine(output,"rcs_actions.c");string original=File.ReadAllText(actionFile);string edited=original.Replace("return test_observer_read(sample);","/* 保留真实驱动的用户修改 */\n    return test_observer_read(sample);");File.WriteAllText(actionFile,edited,new UTF8Encoding(false));d.Points.Reverse();Exporter.Export(d,output);Check(File.ReadAllText(actionFile).Contains("保留真实驱动的用户修改"),"observer user region preserved after waypoint reorder");string stable=File.ReadAllText(actionFile);Exporter.Export(d,output);Check(File.ReadAllText(actionFile)==stable,"repeated export stable");
   string oldPoll="/* Set complete, or return RCS_ACTION_ERROR for a mechanism fault. */\n complete = (1) ? 1 : 0;";string newPoll="/* 设置complete；机构故障返回RCS_ACTION_ERROR。 */\n complete = (1) ? 1 : 0;";string oldRegion=UserRegions.Seal(UserRegions.Block("WP_TEST_POLL",oldPoll));oldRegion=oldRegion.Replace("/* USER CODE BEGIN WP_TEST_POLL */\n","/* USER CODE BEGIN WP_TEST_POLL */\n/* 保留手写 */\n");Check(UserRegions.Merge(oldRegion,UserRegions.Seal(UserRegions.Block("WP_TEST_POLL",newPoll))).Contains("保留手写"),"known comment translation preserves manual body");Throws(()=>UserRegions.Merge(oldRegion,UserRegions.Seal(UserRegions.Block("WP_TEST_POLL",newPoll.Replace("(1)","(0)")))),"real condition change still conflicts with manual edits");
   using(var dialog=new PhaseDialog(d.Points.Last(),d.ActionIncludes,d)){dialog.ShowInTaskbar=false;dialog.Opacity=0;dialog.Show();Application.DoEvents();Check(dialog.CorrectionBox.List.Items.Count==1,"actual middle pane lists template");dialog.CorrectionBox.Remove();Check(!CorrectionRules.Items(d.Points.Last()).Any(),"actual middle pane deletion makes empty");dialog.Close();}
   using(var hardware=new HardwareDialog(Fixture())){hardware.ShowInTaskbar=false;hardware.Opacity=0;hardware.Show();Application.DoEvents();var grid=(PropertyGrid)typeof(HardwareDialog).GetField("grid",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(hardware);Check(grid.Width>=500,"hardware property editor retains readable width");hardware.Close();}
   var flags=BindingFlags.NonPublic|BindingFlags.Public|BindingFlags.Instance;using(var editor=new Editor()){editor.ShowInTaskbar=false;editor.Opacity=0;editor.Show();Application.DoEvents();var t=typeof(Editor);var current=(MapDocument)t.GetField("doc",flags).GetValue(editor);t.GetMethod("BeginChange",flags).Invoke(editor,null);CorrectionRules.Import(current,Profile(Source()));t.GetMethod("EndChange",flags).Invoke(editor,null);Check(((MapDocument)t.GetField("doc",flags).GetValue(editor)).HardwareSources.Count==1,"hardware transaction commits to main document");t.GetMethod("Undo",flags).Invoke(editor,null);Check(!CorrectionRules.Sources((MapDocument)t.GetField("doc",flags).GetValue(editor)).Any(),"hardware global undo");t.GetMethod("Redo",flags).Invoke(editor,null);Check(CorrectionRules.Sources((MapDocument)t.GetField("doc",flags).GetValue(editor)).Count()==1,"hardware global redo");t.GetField("filename",flags).SetValue(editor,Path.Combine(Path.GetFullPath(folder),"hardware-draft.json"));Check((bool)t.GetMethod("Save",flags).Invoke(editor,new object[]{false}),"actual v5 hardware draft saves without validation gate");current=(MapDocument)t.GetField("doc",flags).GetValue(editor);t.GetField("savedJson",flags).SetValue(editor,current.Json());editor.Close();}
   WriteFixture(folder);File.WriteAllText(Path.Combine(folder,"correction-selftest.txt"),"PASS "+count+" correction model/UI checks\n");Console.WriteLine("PASS "+count+" correction model/UI checks");
  }
 }
}
